def mypose(pos, az, tl):
    az_r, tl_r = np.radians(az), np.radians(tl)
    a = [np.cos(tl_r)*np.cos(az_r), np.cos(tl_r)*np.sin(az_r), -np.sin(tl_r)]
    c = [-np.sin(az_r), np.cos(az_r), 0.0]
    return list(rh.pose_from_axes(list(pos), a, c))
